const LAW_SOURCES={
 EG:{ar:'مصر',en:'Egypt',titleAr:'قانون العمل رقم 14 لسنة 2025',titleEn:'Labour Law No. 14 of 2025',summaryAr:'النص الرسمي لقانون العمل المصري منشور لدى وزارة العمل. راجع أحكام العقود، الإجازات، ساعات العمل وإنهاء الخدمة، والقرارات التنفيذية ذات الصلة.',summaryEn:'The Egyptian Ministry of Labour publishes the official law. Check contracts, leave, working hours, termination and applicable implementing decisions.',scopeAr:'تحقق من نطاق المنشأة والعامل؛ لا تُطبَّق الأرقام تلقائيًا من هذا المركز.',scopeEn:'Confirm the employer and worker fall within scope. This hub does not automatically apply entitlements.',sources:[{title:'Ministry of Labour • Official law PDF',url:'https://www.labour.gov.eg/media/0iedik3q/القانون-رقم-14-لسنة-2025-بإصدار-قانون-العمل.pdf'},{title:'Ministry of Labour',url:'https://www.labour.gov.eg/'}]},
 SA:{ar:'السعودية',en:'Saudi Arabia',titleAr:'نظام العمل السعودي',titleEn:'Saudi Labour Law',summaryAr:'دليل الوزارة يقسم النظام إلى التوظيف، العلاقات العمالية، التدريب وظروف العمل. استخدم النسخة المحدثة واللوائح، وليس نسخة قديمة من القانون.',summaryEn:'The ministry organises the law into recruitment, labour relations, training and working conditions. Use current amendments and regulations, rather than an older PDF.',scopeAr:'تحقق من القطاع ونوع العامل، بما في ذلك الأنظمة المنفصلة لبعض الفئات.',scopeEn:'Confirm the sector and worker category; separate rules can apply to some workers.',sources:[{title:'HRSD • Labour Law portal',url:'https://www.hrsd.gov.sa/en/knowledge-centre/نظام-العمل'},{title:'HRSD • Labour law PDF (2025 edition)',url:'https://www.hrsd.gov.sa/sites/default/files/2025-11/labor-law.pdf'}]},
 AE:{ar:'الإمارات',en:'United Arab Emirates',titleAr:'تنظيم علاقات العمل في القطاع الخاص',titleEn:'Private-sector employment law',summaryAr:'البوابة الرسمية تعرض المرسوم بقانون اتحادي 33 لسنة 2021 وتنظيمات العمل في القطاع الخاص، وتشمل حماية العامل والعقود.',summaryEn:'The official portal covers Federal Decree-Law No. 33 of 2021 and private-sector employment regulations, including worker protections and contracts.',scopeAr:'راجع المنطقة الحرة ونطاق القطاع؛ قد توجد أطر قانونية مختلفة.',scopeEn:'Check the free zone and sector: different legal frameworks may apply.',sources:[{title:'UAE Government • Employment laws',url:'https://u.ae/en/information-and-services/jobs/Sector-of-employment/employment-in-the-private-sector/employment-laws-and-regulations-in-the-private-sector'}]},
 GB:{ar:'المملكة المتحدة',en:'United Kingdom',titleAr:'حقوق العمل وتصنيف العامل',titleEn:'Employment rights and worker status',summaryAr:'الحقوق تعتمد على التصنيف: موظف أو عامل أو مستقل. GOV.UK يعرض حقوق الأجر والإجازات والراحة؛ يجب مراجعة مواعيد نفاذ التعديلات الجديدة.',summaryEn:'Rights depend on whether someone is an employee, worker or self-employed. GOV.UK covers pay, holiday and rest; check commencement dates for new reforms.',scopeAr:'التصنيف والجزء من المملكة المتحدة يؤثران على القواعد المطبقة.',scopeEn:'Employment status and the part of the UK affect applicable rules.',sources:[{title:'GOV.UK • Worker status and rights',url:'https://www.gov.uk/employment-status/worker'},{title:'UK Government • Employment changes',url:'https://www.business.gov.uk/campaign/employment-changes/'}]},
 US:{ar:'الولايات المتحدة',en:'United States',titleAr:'FLSA وقوانين الولايات',titleEn:'FLSA and state employment laws',summaryAr:'FLSA ينظم الحد الأدنى للأجر، الإضافي، السجلات وعمل القُصّر. قد تطبق قوانين ولاية أو مدينة بمعايير أعلى، حسب الموظف والاستثناءات.',summaryEn:'The FLSA covers minimum wage, overtime, records and youth employment. State or local rules can provide higher protections; coverage and exemptions matter.',scopeAr:'حدد الولاية والمدينة وتصنيف العامل قبل اعتماد سياسة أو حساب.',scopeEn:'Identify the state, city and worker classification before applying a policy or calculation.',sources:[{title:'US Department of Labor • FLSA',url:'https://www.dol.gov/agencies/whd/flsa'}]},
 CA:{ar:'كندا',en:'Canada',titleAr:'معايير العمل الفيدرالية ومعايير المقاطعات',titleEn:'Federal and provincial labour standards',summaryAr:'معايير العمل الفيدرالية تشمل الأجور والساعات والإجازات وإنهاء الخدمة، لكنها تخص الأعمال الخاضعة للولاية الفيدرالية؛ بقية الأعمال تحتاج مراجعة المقاطعة.',summaryEn:'Federal standards cover pay, hours, leave and termination in federally regulated businesses. Other employers must check the relevant province or territory.',scopeAr:'حدد المقاطعة والقطاع؛ القانون الفيدرالي لا يغطي كل الشركات.',scopeEn:'Identify the province and industry; federal standards do not cover every employer.',sources:[{title:'Government of Canada • Federal labour standards',url:'https://www.canada.ca/en/services/jobs/workplace/federal-labour-standards.html'},{title:'Government of Canada • Federal industries',url:'https://www.canada.ca/en/services/jobs/workplace/federally-regulated-industries.html'}]}
};
let legalCountry=localStorage.getItem('zarqa-country')||'EG',countryMethod='manual';
function lawText(ar,en){return typeof uiLang!=='undefined'&&uiLang==='en'?en:ar;}
function lawsPage(){const c=LAW_SOURCES[legalCountry],names=new Intl.DisplayNames([typeof uiLang!=='undefined'?uiLang:'ar'],{type:'region'});const countries=Object.keys(LAW_SOURCES).concat(legalCountry&&!LAW_SOURCES[legalCountry]?[legalCountry]:[]);return heading(lawText('قوانين العمل. من المصدر.','Labour law. From the source.'),lawText('حدد بلد العمل، ثم راجع المرجع الرسمي ونطاق انطباقه.','Confirm the place of work, then check official sources and applicability.'),btn(lawText('⌖ اكتشاف البلد','⌖ Detect country'),'detectCountry','','primary'),'COUNTRY & LABOUR LAW')+'<div class="filters"><label>'+lawText('بلد العمل','Country of work')+'</label><select id="legalCountry" aria-label="Country of work">'+countries.map(k=>'<option value="'+k+'" '+(legalCountry===k?'selected':'')+'>'+esc(LAW_SOURCES[k]?lawText(LAW_SOURCES[k].ar,LAW_SOURCES[k].en):names.of(k))+'</option>').join('')+'</select><input id="otherCountry" placeholder="'+lawText('بلد آخر: كود من حرفين مثل DE','Other country: two-letter code, e.g. DE')+'" maxlength="2">'+btn(lawText('عرض البلد','Show country'),'otherCountry','','small')+'<span class="filter-note">'+lawText('اقتراح البلد يحتاج تأكيدًا؛ VPN قد يغيّر النتيجة.','Confirm detected country; VPNs may change the result.')+'</span></div><div class="notice blue">'+lawText('موقع المستخدم ليس دائمًا بلد عقد الموظف. هذا المركز يعرض مصادر وملخصات مراجعة؛ لا يغيّر سياسة الإجازات أو الرواتب ولا يُصدر قرارًا قانونيًا.','Your location may differ from the jurisdiction of an employee’s contract. This hub displays reviewed sources and summaries. It does not change leave/payroll policies or issue legal decisions.')+'</div><div class="grid">'+card(c?lawText(c.titleAr,c.titleEn):lawText('راجع تشريعات البلد في NATLEX','Review national legislation in NATLEX'),lawText('مراجعة المصادر: 14 أكتوبر 2026 • ملخص محفوظ، وليس تحديثًا لحظيًا','Sources reviewed: 14 October 2026 • Stored summary, not a live update'),'<p style="font-size:13px;color:var(--text)">'+esc(c?lawText(c.summaryAr,c.summaryEn):lawText('لا يوجد ملخص موثق لهذا البلد في النسخة الحالية. افتح قاعدة منظمة العمل الدولية واختر البلد للبحث في القوانين؛ لن نعرض أحكامًا غير موثقة.','No reviewed country summary is included yet. Open the ILO database and select the country to look up legislation. No unverified rules are displayed.'))+'</p><div class="insight">'+esc(c?lawText(c.scopeAr,c.scopeEn):names.of(legalCountry))+'</div><div class="subheading">'+lawText('المراجع الرسمية','Official references')+'</div>'+(c?.sources||[{title:'ILO • NATLEX',url:'https://natlex.ilo.org/dyn/natlex2/r/natlex/fe/home'}]).map(s=>'<a class="module" href="'+esc(s.url)+'" target="_blank" rel="noopener noreferrer"><span class="action-icon">↗</span><div><h3>'+esc(s.title)+'</h3><p>'+esc(new URL(s.url).hostname)+'</p></div><span>'+lawText('فتح المصدر','Open source')+'</span></a>').join(''))+card(lawText('قبل تطبيق أي قاعدة','Before applying a rule'),lawText('راجع هذه التفاصيل مع HR أو المستشار القانوني','Check these details with HR or legal counsel'),[lawText('بلد العمل الفعلي والعقد','Actual place of work and contract'),lawText('القطاع وتصنيف العامل','Sector and worker classification'),lawText('الولاية أو المقاطعة أو المنطقة الحرة','State, province or free zone'),lawText('تاريخ النفاذ والتعديلات التنفيذية','Effective date and implementing amendments')].map(t=>'<div class="action-row"><span class="action-icon">✓</span><b>'+t+'</b></div>').join('')+'<p style="font-size:10px;margin-top:20px">'+lawText('فتح المصدر الرسمي يعطيك محتواه الحالي. الملخصات داخل التطبيق تحتاج مراجعة عند تحديث التشريعات.','Official links provide current source content. In-app summaries require review when legislation changes.')+'</p>')+'</div>';}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;if(a==='detectCountry'){modal('<h2>'+lawText('اكتشاف البلد باستخدام الشبكة','Detect country from your connection')+'</h2><p>'+lawText('عند الضغط على «اكتشاف»، يتصل المتصفح بخدمة ipapi.co، التي ترى عنوان IP العام. لا نطلب GPS ولا نحفظ عنوان IP. يمكنك تحديد البلد يدويًا بدلًا من ذلك.','Selecting Detect contacts ipapi.co, which sees your public IP address. GPS is not requested and the app does not store your IP. You can choose your country manually instead.')+'</p><div class="form-actions">'+btn(lawText('اكتشاف','Detect'),'confirmDetect','','primary')+btn(lawText('اختيار يدوي','Choose manually'),'close')+'</div>');}
if(a==='confirmDetect'){el.disabled=true;try{const r=await fetch('https://ipapi.co/country/',{signal:AbortSignal.timeout(8000),credentials:'omit',referrerPolicy:'no-referrer'});const code=(await r.text()).trim();if(!r.ok||!/^[A-Z]{2}$/.test(code))throw Error('lookup');const names=new Intl.DisplayNames([uiLang],{type:'region'});modal('<h2>'+lawText('البلد المقترح: ','Suggested country: ')+esc(names.of(code))+'</h2><p>'+lawText('النتيجة تقريبية بناءً على الشبكة. هل هذا بلد العمل الذي تريد مراجعة قوانينه؟','This is an approximate network result. Is this the country of work whose laws you want to review?')+'</p><div class="form-actions">'+btn(lawText('تأكيد وعرض المصادر','Confirm and show sources'),'confirmCountry',code,'primary')+'</div>');}catch(err){toast(lawText('تعذر اكتشاف البلد. اختر بلد العمل يدويًا.','Country detection failed. Choose the country of work manually.'));closeModal();}}
if(a==='confirmCountry'){legalCountry=el.dataset.id;localStorage.setItem('zarqa-country',legalCountry);countryMethod='ip-confirmed';closeModal();navigate('laws');}
if(a==='otherCountry'){const code=$('otherCountry').value.trim().toUpperCase();try{if(!/^[A-Z]{2}$/.test(code)||new Intl.DisplayNames(['en'],{type:'region'}).of(code)===code)throw Error();legalCountry=code;localStorage.setItem('zarqa-country',code);render();}catch(err){toast(lawText('أدخل كود بلد صحيحًا مثل DE أو FR.','Enter a valid country code such as DE or FR.'));}}
});
document.addEventListener('change',e=>{if(e.target.id==='legalCountry'){legalCountry=e.target.value;localStorage.setItem('zarqa-country',legalCountry);render();}});
